import dspy
from dspy.utils.dummies import DummyLM


class MyProgram(dspy.Module):
    def __init__(self):
        super().__init__()
        self.cot = dspy.ChainOfThought("question -> answer")

    def forward(self, question):
        return self.cot(question=question)


dspy.configure(
    lm=DummyLM(
        [
            {"reasoning": "N/A", "answer": "first"},
            {"reasoning": "N/A", "answer": "second"},
        ]
    )
)
program = MyProgram()
results = dspy.Parallel()(
    [
        (program, {"question": "Q1"}),
        (program, {"question": "Q2"}),
    ]
)

print("answers:", [result.answer for result in results])
print("history_lengths:", len(program.history), len(program.cot.history), len(program.cot.predict.history))
assert len(program.history) == 2
assert len(program.cot.history) == 2
assert len(program.cot.predict.history) == 2
